from solution import words_string
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference_words_string(s):
    """Obviously-correct reference: split on ',' or ' ', drop empties, preserve order."""
    words = []
    current = []
    for ch in s:
        if ch == ',' or ch == ' ':
            if current:
                words.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        words.append(''.join(current))
    return words


# ---- explicit spec examples ----

def test_example_hi_my_name_is_john():
    assert words_string("Hi, my name is John") == ["Hi", "my", "name", "is", "John"]


def test_example_one_through_six():
    assert words_string("One, two, three, four, five, six") == ["One", "two", "three", "four", "five", "six"]


# ---- boundary examples ----

def test_empty_string_returns_empty_list():
    assert words_string("") == []


def test_single_word_no_delimiters():
    assert words_string("Hello") == ["Hello"]


def test_only_spaces_returns_empty():
    assert words_string("   ") == []


def test_only_commas_returns_empty():
    assert words_string(",,,") == []


def test_only_mixed_delimiters_returns_empty():
    assert words_string(" , , ,   ,, ") == []


def test_leading_trailing_delimiters_ignored():
    assert words_string("  , Hi, my name , ") == ["Hi", "my", "name"]
    assert words_string(",One,") == ["One"]
    assert words_string(" John ") == ["John"]


def test_consecutive_delimiters_produce_no_empty_words():
    assert words_string("a,,b") == ["a", "b"]
    assert words_string("a  b") == ["a", "b"]
    assert words_string("a, ,b") == ["a", "b"]
    assert words_string("a,,,   ,,,b") == ["a", "b"]


def test_space_only_separation():
    assert words_string("Hi my name is John") == ["Hi", "my", "name", "is", "John"]


def test_comma_only_separation_no_spaces():
    assert words_string("One,two,three") == ["One", "two", "three"]


# ---- property-based tests ----

@given(st.text(alphabet="abAB ,", max_size=30))
def test_property_matches_reference_model(s):
    assert words_string(s) == reference_words_string(s)


@given(st.text(alphabet="abAB ,", max_size=30))
def test_property_no_empty_words_and_no_delimiters_inside_words(s):
    result = words_string(s)
    assert isinstance(result, list)
    for w in result:
        assert isinstance(w, str)
        assert w != ""
        assert "," not in w
        assert " " not in w


@given(st.lists(st.text(alphabet="abcXYZ", min_size=1, max_size=8), min_size=0, max_size=8))
def test_property_join_with_single_space_roundtrip(words):
    s = " ".join(words)
    assert words_string(s) == words


@given(st.lists(st.text(alphabet="abcXYZ", min_size=1, max_size=8), min_size=0, max_size=8))
def test_property_join_with_comma_roundtrip(words):
    s = ",".join(words)
    assert words_string(s) == words


@given(
    st.lists(st.text(alphabet="abcXYZ", min_size=1, max_size=5), min_size=0, max_size=6),
    st.lists(st.sampled_from([" ", ",", "  ", ",,", " , ", " ,", ", "]), min_size=0, max_size=7),
)
def test_property_arbitrary_delimiter_runs_preserve_order(words, seps):
    # Interleave words with arbitrary non-empty runs of ',' and ' '.
    if not words:
        return
    parts = [words[0]]
    for i, w in enumerate(words[1:]):
        sep = seps[i % len(seps)] if seps else " "
        parts.append(sep)
        parts.append(w)
    s = "".join(parts)
    assert words_string(s) == words


@given(st.text(alphabet="abAB ,", max_size=30))
def test_property_comma_space_interchange_does_not_change_result(s):
    # Replacing every comma with a space must not change the split.
    assert words_string(s) == words_string(s.replace(",", " "))


@given(st.text(alphabet="abAB ,", max_size=30))
def test_property_extra_delimiters_are_idempotent(s):
    result = words_string(s)
    # Re-joining with doubled delimiters and re-splitting is stable.
    rejoined_space = "  ".join(result)
    rejoined_comma = ",,".join(result)
    rejoined_mixed = " , ".join(result)
    assert words_string(rejoined_space) == result
    assert words_string(rejoined_comma) == result
    assert words_string(rejoined_mixed) == result


@given(st.text(alphabet="abAB ,", max_size=30))
def test_property_leading_trailing_delimiters_do_not_change_result(s):
    result = words_string(s)
    assert words_string("  " + s + "  ") == result
    assert words_string(",," + s + ",,") == result
    assert words_string(" , " + s + " , ") == result


@given(st.text(alphabet="abcXYZ", min_size=1, max_size=10))
def test_property_single_word_without_delimiters_returns_singleton(word):
    assert words_string(word) == [word]
